insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('executive-function-profiling', 'Executive Function Profiling', 'Planning, inhibition, working memory, and task-switching — the control processes behind goal-directed behavior.', 'Executive Function Profiling is built on the scale structure of the BRIEF (Behavior Rating Inventory of Executive Function) — the clinical standard for self- and informant-rated executive function, widely used alongside performance-based tests. It measures eight control processes: Inhibit, Shift, Emotional Control, Initiate, Working Memory, Plan/Organize, Task Monitor, and Self-Monitor.', 'layers', (select id from assessment_categories where key = 'cognitive'), ('hybrid')::assessment_engine_type, ('hard')::assessment_difficulty, 20, 24, false, ('premium')::assessment_access, ('published')::assessment_status)
