insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'executive-function-profiling'), 'overall', 0, 30, 'Developing', 'Several control processes feel effortful right now — worth checking the eight scores above for which specific ones stand out most.', ARRAY['Pick the single lowest-scoring scale above and focus on one concrete habit for it (e.g. a written task list for Plan/Organize)', 'External supports (timers, checklists, written reminders) compensate well for executive function gaps — use them deliberately, not as a last resort', 'Notice patterns across your day: executive function is often more fatigue-sensitive than other cognitive measures']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'executive-function-profiling'), 'overall', 31, 50, 'Average', 'A typical mixed profile — some control processes stronger than others.', ARRAY['Look at your two lowest scales above and build one small structural habit for each', 'Notice whether your weaker scales cluster (e.g. Inhibit + Emotional Control often move together) — that pattern is informative']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'executive-function-profiling'), 'overall', 51, 70, 'Strong', 'Reliable executive control across most processes, with room to grow in one or two specific scales.', ARRAY['Push your weakest scale specifically rather than practicing generically', 'Strong executive function compounds well with other cognitive strengths — check your Brain Profile for where it''s paying off most']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'executive-function-profiling'), 'overall', 71, 85, 'Very Strong', 'Consistently strong self-reported control across planning, inhibition, working memory, and task-switching.', ARRAY['This level of executive control is a genuine asset in complex, multi-step, or high-distraction work', 'Consider whether your Self-Monitor score matches how others actually perceive you — it''s worth checking that gap periodically']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'executive-function-profiling'), 'overall', 86, 100, 'Exceptional', 'Uniformly strong across all eight executive function scales.', ARRAY['This is a strong foundation for demanding, multi-threaded work — notice where it''s already paying off', 'Since this is self-report, periodically sanity-check it against how consistently your actual follow-through matches your intentions']::text[], NULL, 5);
